_FUNCTIONS = {
    "min": (1, None, min),
    "max": (1, None, max),
    "abs": (1, 1, abs),
}

_OPERATORS = ("**", "//", "+", "-", "*", "/", "%", "(", ")", ",")


def _is_name_start(ch):
    return ch == "_" or ("a" <= ch <= "z") or ("A" <= ch <= "Z")


def _is_name_char(ch):
    return _is_name_start(ch) or ("0" <= ch <= "9")


def _tokenize(text):
    """Return a list of (kind, value, pos). A bad character becomes a
    ("bad", ch, pos) token so the parser reports it only when it reaches it;
    the list always ends with ("end", None, len(text))."""
    tokens = []
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch in " \t":
            i += 1
            continue
        start = i
        if ch.isdigit() and ch in "0123456789" or (
            ch == "." and i + 1 < n and text[i + 1] in "0123456789"
        ):
            while i < n and text[i] in "0123456789":
                i += 1
            is_float = False
            if i < n and text[i] == ".":
                is_float = True
                i += 1
                while i < n and text[i] in "0123456789":
                    i += 1
            literal = text[start:i]
            value = float(literal) if is_float else int(literal)
            tokens.append(("num", value, start))
            continue
        if _is_name_start(ch):
            while i < n and _is_name_char(text[i]):
                i += 1
            tokens.append(("name", text[start:i], start))
            continue
        for op in _OPERATORS:
            if text.startswith(op, i):
                tokens.append(("op", op, start))
                i += len(op)
                break
        else:
            tokens.append(("bad", ch, start))
            break  # nothing after a bad character can matter
    tokens.append(("end", None, n))
    return tokens


class _Parser:
    def __init__(self, text):
        self.tokens = _tokenize(text)
        self.index = 0

    def peek(self):
        return self.tokens[self.index]

    def advance(self):
        tok = self.tokens[self.index]
        self.index += 1
        return tok

    def is_op(self, *ops):
        kind, value, _ = self.peek()
        return kind == "op" and value in ops

    def fail(self):
        kind, value, pos = self.peek()
        if kind == "end":
            raise CalcError("unexpected end of expression", pos)
        if kind == "bad":
            raise CalcError(f"unexpected character {value!r}", pos)
        raise CalcError(f"unexpected token {value!r}", pos)

    def expect(self, op):
        if not self.is_op(op):
            self.fail()
        return self.advance()

    # Grammar --------------------------------------------------------------
    def parse(self):
        node = self.expr()
        if self.peek()[0] != "end":
            self.fail()
        return node

    def expr(self):
        node = self.term()
        while self.is_op("+", "-"):
            _, op, pos = self.advance()
            node = ("bin", op, pos, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.is_op("*", "/", "//", "%"):
            _, op, pos = self.advance()
            node = ("bin", op, pos, node, self.unary())
        return node

    def unary(self):
        # Iterative over the sign prefix to avoid deep recursion on "----1".
        signs = []
        while self.is_op("+", "-"):
            signs.append(self.advance()[1])
        node = self.power()
        for sign in reversed(signs):
            node = ("neg", node) if sign == "-" else ("pos", node)
        return node

    def power(self):
        node = self.atom()
        if self.is_op("**"):
            _, _, pos = self.advance()
            node = ("bin", "**", pos, node, self.unary())
        return node

    def atom(self):
        kind, value, pos = self.peek()
        if kind == "num":
            self.advance()
            return ("num", value)
        if kind == "name":
            self.advance()
            if self.is_op("("):
                self.advance()
                args = []
                if not self.is_op(")"):
                    args.append(self.expr())
                    while self.is_op(","):
                        self.advance()
                        args.append(self.expr())
                self.expect(")")
                return ("call", value, pos, args)
            return ("var", value, pos)
        if kind == "op" and value == "(":
            self.advance()
            node = self.expr()
            self.expect(")")
            return node
        self.fail()


def _binary(op, pos, left, right):
    try:
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op in ("/", "//", "%"):
            if right == 0:
                raise CalcError("division by zero", pos)
            if op == "/":
                return left / right
            if op == "//":
                return left // right
            return left % right
        # "**"
        result = left ** right
    except ZeroDivisionError:
        if op == "**":
            raise CalcError("power is not a real number", pos) from None
        raise CalcError("division by zero", pos) from None
    except OverflowError:
        raise CalcError("result too large", pos) from None
    if isinstance(result, complex):
        raise CalcError("power is not a real number", pos)
    return result


def _eval(node, variables):
    tag = node[0]
    if tag == "num":
        return node[1]
    if tag == "neg":
        return -_eval(node[1], variables)
    if tag == "pos":
        return +_eval(node[1], variables)
    if tag == "var":
        _, name, pos = node
        if name not in variables:
            raise CalcError(f"unknown variable {name!r}", pos)
        return variables[name]
    if tag == "call":
        _, name, pos, args = node
        if name not in _FUNCTIONS:
            if name in variables:
                raise CalcError(f"variable {name!r} is not a function", pos)
            raise CalcError(f"unknown function {name!r}", pos)
        lo, hi, func = _FUNCTIONS[name]
        if len(args) < lo or (hi is not None and len(args) > hi):
            raise CalcError(f"wrong number of arguments to {name}()", pos)
        values = [_eval(arg, variables) for arg in args]
        return func(*values) if name != "abs" else func(values[0])
    _, op, pos, left, right = node
    lval = _eval(left, variables)
    rval = _eval(right, variables)
    return _binary(op, pos, lval, rval)


def evaluate(expression, variables=None):
    if variables is None:
        variables = {}
    tree = _Parser(expression).parse()
    return _eval(tree, variables)

