"""A small arithmetic evaluator.

    evaluate(expression, variables=None) -> int | float

GRAMMAR, lowest precedence first::

    expr   := term (("+" | "-") term)*
    term   := unary (("*" | "/" | "//" | "%") unary)*
    unary  := ("+" | "-") unary | power
    power  := atom ("**" unary)?
    atom   := NUMBER | NAME | NAME "(" [expr ("," expr)*] ")" | "(" expr ")"

So "**" is right-associative (2 ** 3 ** 2 == 512) and binds tighter than a
unary minus on its LEFT (-2 ** 2 == -4) but not on its right (2 ** -1 == 0.5).
"+" and "-" (binary), "*", "/", "//" and "%" are left-associative.

NUMBER is digits with an optional fraction: "12", "3.5", ".5" or "5.". A
number written with a "." is a float, otherwise an int ("007" is the int 7).
NAME is a letter or "_" followed by letters, digits or "_". Spaces and tabs
may appear between tokens.

VALUES follow Python's own int/float arithmetic: "/" always gives a float,
"//" floors, "%" takes the sign of the divisor, "**" is Python's power.

NAMES: a NAME followed by "(" is a FUNCTION call; any other NAME is a
VARIABLE, looked up in the ``variables`` dict (None means no variables). The
functions are ``min`` and ``max`` (one or more arguments) and ``abs`` (exactly
one argument). Functions are not variables, and a variable cannot be called.

ERRORS raise ``CalcError`` (a ValueError defined in this module) whose ``pos``
attribute is the index in ``expression`` where the problem was found:

* an unexpected character, or a token where it does not belong: the index
  where that character or token starts (e.g. "1 + * 2" -> 4, "1 2" -> 2,
  "2 $ 3" -> 2, ")" -> 0);
* the expression ends too early ("1 +", "(1", "max(1," and "" too):
  ``pos == len(expression)``;
* an unknown variable or function, a variable called like a function, or a
  function given the wrong number of arguments: the index where its NAME
  starts;
* division or modulo by zero ("/", "//" or "%" with a zero right-hand side):
  the index of that operator;
* a power Python cannot compute as a real number (0 ** -1, (-8) ** 0.5): the
  index of the "**".
"""


class CalcError(ValueError):
    def __init__(self, message, pos):
        super().__init__(f"{message} (at {pos})")
        self.pos = pos


def evaluate(expression, variables=None):
    s = expression
    n = len(s)
    i = 0

    def error(msg, pos):
        raise CalcError(msg, pos)

    def skip_spaces():
        nonlocal i
        while i < n and s[i] in " \t":
            i += 1

    def peek_operator():
        """Return the operator token at the current position, or None."""
        skip_spaces()
        if s.startswith("**", i):
            return "**"
        for op in ("//", "+", "-", "*", "/", "%", "(", ")", ","):
            if s.startswith(op, i):
                return op
        return None

    def take_operator(op):
        """Consume the operator ``op`` if present; return True/False."""
        nonlocal i
        if peek_operator() == op:
            i += len(op)
            return True
        return False

    def parse_number():
        nonlocal i
        start = i
        seen_dot = False
        while i < n and (s[i].isdigit() or (s[i] == "." and not seen_dot)):
            if s[i] == ".":
                seen_dot = True
            i += 1
        if i == start:
            return None
        text = s[start:i]
        return float(text) if seen_dot else int(text)

    def parse_name():
        nonlocal i
        if not (s[i].isalpha() or s[i] == "_"):
            return None
        start = i
        i += 1
        while i < n and (s[i].isalnum() or s[i] == "_"):
            i += 1
        return s[start:i]

    def parse_expr():
        value = parse_term()
        while True:
            if take_operator("+"):
                value = value + parse_term()
            elif take_operator("-"):
                value = value - parse_term()
            else:
                return value

    def parse_term():
        value = parse_unary()
        while True:
            op = peek_operator()
            if op not in ("*", "/", "//", "%"):
                return value
            i += len(op)
            rhs = parse_unary()
            if op in ("/", "//", "%") and rhs == 0:
                error(f"division by zero for '{op}'", i - len(op))
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = value / rhs
            elif op == "//":
                value = value // rhs
            else:
                value = value % rhs

    def parse_unary():
        op = peek_operator()
        if op in ("+", "-"):
            i += 1
            value = parse_unary()
            return value if op == "+" else -value
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek_operator() == "**":
            i += 2
            exponent = parse_unary()  # right-associative; allows -1, +2, -(-3)
            try:
                result = base ** exponent
            except ZeroDivisionError:
                error("division by zero for '**'", i - 2)
            except (ValueError, OverflowError, TypeError) as exc:
                error(f"cannot compute '{base} ** {exponent}': {exc}", i - 2)
            return result
        return base

    def parse_atom():
        skip_spaces()
        if i >= n:
            error("expression ends too early", n)

        if s.startswith("**", i) or s[0] in "+-*/%,)":
            # A token that cannot start an atom.  A "**" or "+" or "-" here
            # has already been consumed by unary/power; "*" "/" "%" ")" ","
            # never belong here.
            if s[i] in "*/)%,)":
                error(f"unexpected '{s[i]}'", i)
            error(f"unexpected '{s[i]}'", i)

        # Function call: NAME "(" args ")".
        if s[i].isalpha() or s[i] == "_":
            save = i
            name = parse_name()
            skip_spaces()
            if peek_operator() == "(":
                i += 1  # consume "("
                args = []
                if peek_operator() != ")":
                    args.append(parse_expr())
                    while take_operator(","):
                        args.append(parse_expr())
                if not take_operator(")"):
                    error("expression ends too early", n)
                check_call(name, args, save)
                return apply_call(name, args, save)

            # A plain variable (or function name used without calling).
            if name in ("min", "max", "abs"):
                if peek_operator() is None and i < n:
                    error(f"unexpected '{s[i]}'", i)
                if not variables and (variables is None or name not in variables):
                    pass  # functions are never variables
                error(f"'{name}' is a function, not a variable", save)
            if variables and name in variables:
                return variables[name]
            error(f"unknown variable '{name}'", save)

        value = parse_number()
        if value is not None:
            return value

        if take_operator("("):
            value = parse_expr()
            if not take_operator(")"):
                error("expression ends too early", n)
            return value

        error(f"unexpected character '{s[i]}'", i)

    def check_call(name, args, pos):
        if name not in ("min", "max", "abs"):
            error(f"unknown function '{name}'", pos)
        if name == "abs" and len(args) != 1:
            error(f"abs() takes exactly 1 argument ({len(args)} given)", pos)

    def apply_call(name, args, pos):
        if name == "abs":
            return abs(args[0])
        return min(args) if name == "min" else max(args)

    skip_spaces()
    if i >= n:
        error("expression ends too early", n)
    value = parse_expr()
    skip_spaces()
    if i < n:
        error(f"unexpected '{s[i]}'", i)
    return value

